import {
  DEFAULT_IMAGE_MODEL,
  DEFAULT_MEDIA_MODEL,
  DEFAULT_TEXT_MODEL,
  IMAGE_PROVIDER_ID,
  TEXT_PROVIDER_ID,
  WEB_FETCH_PROVIDER_ID,
  WEB_SEARCH_PROVIDER_ID,
} from "../constants.js";

export function kitchenTextProviderConfig() {
  // Looks like a real provider config, but stays credential-free and local so
  // installs can use it in CI, Crabpot, and plugin-inspector.
  return {
    baseUrl: "kitchen-sink://local",
    apiKey: "[REDACTED]",
    auth: "token",
    api: "kitchen-sink",
    models: [kitchenTextModelDefinition()],
  };
}

export function kitchenTextModelDefinition() {
  return {
    id: DEFAULT_TEXT_MODEL,
    name: "Kitchen Sink Text Fixture",
    api: "kitchen-sink",
    input: ["text"],
    cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
    contextWindow: 8192,
    maxTokens: 2048,
    description: "Deterministic OpenClaw plugin text-provider fixture.",
  };
}

export function kitchenTextRuntimeModelDefinition() {
  return {
    ...kitchenTextModelDefinition(),
    provider: TEXT_PROVIDER_ID,
    baseUrl: "kitchen-sink://local",
    reasoning: false,
  };
}

export function createKitchenTextStream(model, context) {
  // Emit the same coarse lifecycle events a streaming text provider would emit;
  // consumers can test stream handling without a live model.
  const stream = createAssistantMessageEventStream();
  queueMicrotask(() => {
    const prompt = extractLastUserPrompt(context);
    const text = kitchenTextResponse(prompt);
    const message = {
      role: "assistant",
      content: [{ type: "text", text }],
      api: model?.api || "kitchen-sink",
      provider: TEXT_PROVIDER_ID,
      model: model?.id || DEFAULT_TEXT_MODEL,
      usage: estimateUsage(prompt, text),
      stopReason: "stop",
      timestamp: Date.now(),
    };
    stream.push({ type: "start", partial: { ...message, content: [] } });
    stream.push({ type: "text_start", contentIndex: 0, partial: { ...message, content: [] } });
    stream.push({ type: "text_delta", contentIndex: 0, delta: text, partial: message });
    stream.push({ type: "text_end", contentIndex: 0, content: text, partial: message });
    stream.push({ type: "done", reason: "stop", message });
    stream.end(message);
  });
  return stream;
}

export function kitchenTextResponse(prompt) {
  const normalized = normalizePrompt(prompt, "kitchen sink text inference");
  if (/\b(image|picture|draw|generate)\b/i.test(normalized)) {
    return [
      "Kitchen Sink text fixture:",
      `prompt="${normalized}"`,
      `I would route this to ${IMAGE_PROVIDER_ID}/${DEFAULT_IMAGE_MODEL}, create a queued image job, wait for completion, then return the bundled kitchen_sink_office.png asset with PNG metadata.`,
    ].join(" ");
  }
  if (/\b(search|find|lookup|web)\b/i.test(normalized)) {
    return [
      "Kitchen Sink text fixture:",
      `prompt="${normalized}"`,
      `I would call ${WEB_SEARCH_PROVIDER_ID} for ranked fixture results and ${WEB_FETCH_PROVIDER_ID} for deterministic document fetches.`,
    ].join(" ");
  }
  if (/\b(rate limit|timeout|fail|error)\b/i.test(normalized)) {
    return [
      "Kitchen Sink text fixture:",
      `prompt="${normalized}"`,
      "Failure fixtures are available: rate limit returns 429 with retry metadata, timeout returns 504, and fail returns a deterministic provider error.",
    ].join(" ");
  }
  return [
    "Kitchen Sink text fixture:",
    `prompt="${normalized}"`,
    "Available realistic surfaces: direct prefix, registered tools, image provider lifecycle, media understanding, web search, web fetch, channel health, hooks, detached tasks, and text provider catalog.",
  ].join(" ");
}

export function kitchenImageDescription(prompt, count) {
  return [
    `Kitchen Sink media fixture described ${count || 1} image${count === 1 ? "" : "s"}.`,
    `Prompt: ${normalizePrompt(prompt, "describe kitchen sink image")}.`,
    "Visible content: the bundled kitchen_sink_office PNG: an office lobby scene with a lobster-costumed figure holding a real sink.",
  ].join(" ");
}

export function estimateUsage(prompt = "", text = "") {
  const input = estimateTokens(prompt);
  const output = estimateTokens(text);
  return {
    input,
    output,
    cacheRead: 0,
    cacheWrite: 0,
    totalTokens: input + output,
    cost: {
      input: 0,
      output: 0,
      cacheRead: 0,
      cacheWrite: 0,
      total: 0,
    },
  };
}

function createAssistantMessageEventStream() {
  const queue = [];
  const waiters = [];
  let done = false;
  let finalResult;
  let resolveResult;
  const resultPromise = new Promise((resolve) => {
    resolveResult = resolve;
  });

  return {
    push(event) {
      if (done) {
        return;
      }
      if (event.type === "done" || event.type === "error") {
        finalResult = event.type === "done" ? event.message : event.error;
        done = true;
        resolveResult(finalResult);
      }
      const waiter = waiters.shift();
      if (waiter) {
        waiter({ value: event, done: false });
      } else {
        queue.push(event);
      }
    },
    end(result) {
      if (result !== undefined && finalResult === undefined) {
        finalResult = result;
        resolveResult(result);
      }
      done = true;
      while (waiters.length > 0) {
        waiters.shift()({ value: undefined, done: true });
      }
    },
    async *[Symbol.asyncIterator]() {
      while (true) {
        if (queue.length > 0) {
          yield queue.shift();
        } else if (done) {
          return;
        } else {
          const next = await new Promise((resolve) => waiters.push(resolve));
          if (next.done) {
            return;
          }
          yield next.value;
        }
      }
    },
    result() {
      return resultPromise;
    },
  };
}

function extractLastUserPrompt(context) {
  const messages = Array.isArray(context?.messages) ? context.messages : [];
  for (let index = messages.length - 1; index >= 0; index -= 1) {
    const message = messages[index];
    if (message?.role !== "user") {
      continue;
    }
    if (typeof message.content === "string") {
      return message.content;
    }
    if (Array.isArray(message.content)) {
      const text = message.content
        .filter((item) => item?.type === "text" && typeof item.text === "string")
        .map((item) => item.text)
        .join(" ")
        .trim();
      if (text) {
        return text;
      }
    }
  }
  return "kitchen sink text inference";
}

function estimateTokens(text) {
  return Math.max(1, Math.ceil(String(text).trim().split(/\s+/).filter(Boolean).length * 1.35));
}

function normalizePrompt(value, fallback) {
  const text = String(value ?? "").replace(/\s+/g, " ").trim();
  return text || fallback;
}

import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { DEFAULT_IMAGE_MODEL, PLUGIN_ID } from "../constants.js";

// Use a real bundled PNG so image-provider consumers exercise binary payloads,
// data URLs, hashes, and dimensions instead of a text-only mock.
const KITCHEN_SINK_OFFICE_IMAGE_FILE = "kitchen_sink_office.png";
const KITCHEN_SINK_OFFICE_IMAGE = readFileSync(
  new URL(`../assets/${KITCHEN_SINK_OFFICE_IMAGE_FILE}`, import.meta.url),
);
const KITCHEN_SINK_OFFICE_SHA256 = sha256Hex(KITCHEN_SINK_OFFICE_IMAGE);

const KITCHEN_IMAGE_FIXTURES = [
  {
    id: "office-lobby-sink",
    label: "Kitchen Sink Office",
    assetName: KITCHEN_SINK_OFFICE_IMAGE_FILE,
    buffer: KITCHEN_SINK_OFFICE_IMAGE,
    sha256: KITCHEN_SINK_OFFICE_SHA256,
    mimeType: "image/png",
    width: 1024,
    height: 1024,
    description: "office lobby scene with a lobster-costumed figure holding a real sink",
    source: "bundled-real-image",
  },
];

export function createKitchenSinkImageAsset({
  prompt,
  jobId,
  scenario = "image.generate",
  model = DEFAULT_IMAGE_MODEL,
}) {
  const fixture = selectKitchenImageFixture(prompt);
  const buffer = Buffer.from(fixture.buffer);
  const seed = stableHash(`${jobId}:${prompt}:${fixture.id}`);
  return {
    buffer,
    mimeType: fixture.mimeType,
    fileName: `${jobId}.png`,
    dataUrl: `data:${fixture.mimeType};base64,${buffer.toString("base64")}`,
    revisedPrompt: `Kitchen Sink office image fixture: ${prompt}`,
    metadata: {
      kitchenSink: true,
      assetId: fixture.id,
      assetName: fixture.assetName,
      source: fixture.source,
      model,
      width: fixture.width,
      height: fixture.height,
      sizeBytes: buffer.byteLength,
      sha256: fixture.sha256,
      contentHash: fixture.sha256.slice(0, 16),
      seed,
      finishReason: "success",
      pluginId: PLUGIN_ID,
      scenarioId: scenario,
      jobId,
      prompt,
    },
  };
}

function selectKitchenImageFixture(_prompt) {
  // Single fixture today, prompt-aware selection later if we add more real
  // assets for edit/upscale/multi-image scenarios.
  return KITCHEN_IMAGE_FIXTURES[0];
}

function sha256Hex(buffer) {
  return createHash("sha256").update(buffer).digest("hex");
}

function stableHash(input) {
  let hash = 2166136261;
  for (let index = 0; index < input.length; index += 1) {
    hash ^= input.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16).padStart(8, "0");
}

#!/usr/bin/env node

import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";

const repoRoot = process.cwd();
const tempRoot = mkdtempSync(path.join(tmpdir(), "kitchen-sink-install-"));
const keepTemp = process.env.KEEP_KITCHEN_INSTALL_SMOKE === "1";
let lastStdout = "";
let failure;

try {
  const packDir = path.join(tempRoot, "pack");
  mkdirSync(packDir, { recursive: true });
  const kitchenSinkTarball = packPackage(repoRoot, packDir);
  const packageJson = JSON.parse(readFileSync(path.join(repoRoot, "package.json"), "utf8"));
  const openClawVersion = packageJson.devDependencies?.openclaw;
  assert.equal(typeof openClawVersion, "string", "devDependencies.openclaw must be pinned");
  const localOpenClawTarball = packLocalOpenClawPackage(packDir, openClawVersion);

  const projectDir = path.join(tempRoot, "consumer");
  mkdirSync(projectDir, { recursive: true });
  const hostInstallSpec = localOpenClawTarball ?? `openclaw@${openClawVersion}`;
  const installSpecs = [hostInstallSpec, kitchenSinkTarball];
  run(
    "npm",
    [
      "install",
      "--prefix",
      projectDir,
      "--package-lock=false",
      "--ignore-scripts",
      "--no-audit",
      "--no-fund",
      ...installSpecs,
    ],
    { cwd: tempRoot },
  );

  const packageDir = path.join(projectDir, "node_modules", "@openclaw", "kitchen-sink");
  const installedPackageJson = JSON.parse(readFileSync(path.join(packageDir, "package.json"), "utf8"));
  const installedHostPackageJson = JSON.parse(
    readFileSync(path.join(projectDir, "node_modules", "openclaw", "package.json"), "utf8"),
  );
  assert.equal(installedPackageJson.name, "@openclaw/kitchen-sink");
  assert.equal(installedPackageJson.version, packageJson.version);
  assert.equal(installedHostPackageJson.version, openClawVersion);

  const probeFile = path.join(projectDir, "probe.mjs");
  writeFileSync(probeFile, readFileSync(new URL("./fixtures/installed-consumer-probe.mjs", import.meta.url), "utf8"));
  run(process.execPath, [probeFile], { cwd: projectDir });

  const inspectorBin = path.join(repoRoot, "node_modules", ".bin", "plugin-inspector");
  run(inspectorBin, ["check", "--config", "plugin-inspector.config.json", "--no-openclaw", "--runtime", "--mock-sdk"], {
    cwd: packageDir,
    env: {
      ...process.env,
      PLUGIN_INSPECTOR_EXECUTE_ISOLATED: "1",
    },
  });

  console.log(`Installed package smoke OK: ${installedPackageJson.name}@${installedPackageJson.version}`);
} catch (error) {
  failure = error;
} finally {
  if (!keepTemp) {
    rmSync(tempRoot, { recursive: true, force: true });
  } else {
    console.log(`Kept install smoke temp dir: ${tempRoot}`);
  }
}

if (failure) {
  process.stderr.write(`${failure instanceof Error ? failure.message : String(failure)}\n`);
  process.exitCode = Number.isInteger(failure?.exitCode) ? failure.exitCode : 1;
}

function run(command, args, options = {}) {
  const result = spawnSync(command, args, {
    cwd: options.cwd,
    env: options.env || process.env,
    encoding: "utf8",
    stdio: ["ignore", "pipe", "pipe"],
  });
  lastStdout = result.stdout;
  if (result.status !== 0) {
    process.stdout.write(result.stdout);
    process.stderr.write(result.stderr);
    const error = new Error(`${command} exited with status ${result.status ?? 1}`);
    error.exitCode = result.status ?? 1;
    throw error;
  }
}

function packPackage(packageRoot, packDir, options = {}) {
  const args = ["pack", "--json", "--pack-destination", packDir];
  if (options.ignoreScripts) {
    args.push("--ignore-scripts");
  }
  run("npm", args, { cwd: packageRoot });
  // npm 12 keys pack results by package name; npm 10/11 return an array.
  const packOutput = Object.values(JSON.parse(lastStdout));
  return path.join(packDir, packOutput[0].filename);
}

function packLocalOpenClawPackage(packDir, expectedVersion) {
  const packageRoot = process.env.OPENCLAW_PACKAGE_ROOT?.trim();
  if (!packageRoot) {
    return undefined;
  }
  const resolvedRoot = path.resolve(packageRoot);
  const packageJson = JSON.parse(readFileSync(path.join(resolvedRoot, "package.json"), "utf8"));
  assert.equal(packageJson.name, "openclaw");
  assert.equal(packageJson.version, expectedVersion);
  return packPackage(resolvedRoot, packDir, { ignoreScripts: true });
}

import { readFileSync } from "node:fs";
import path from "node:path";
import { readOpenClawSurface, registrarProbeExclusions } from "./openclaw-surface.mjs";

const rootDir = path.resolve(import.meta.dirname, "..");
const surface = readOpenClawSurface();
const hooksSource = read("src/generated-hooks.js");
const registrarsSource = read("src/generated-registrars.js");
const sdkImportsSource = read("src/generated-sdk-imports.ts");
const manifest = JSON.parse(read("openclaw.plugin.json"));

const errors = [];

for (const hook of surface.hooks) {
  if (!hooksSource.includes(`api.on(${JSON.stringify(hook)}`)) {
    errors.push(`missing hook coverage: ${hook}`);
  }
}

for (const registrar of surface.registrars) {
  const hasProbe = registrarsSource.includes(`api.${registrar}(`);
  if (Object.hasOwn(registrarProbeExclusions, registrar)) {
    if (hasProbe) {
      errors.push(`excluded registrar must not have a runtime probe: ${registrar}`);
    }
  } else if (!hasProbe) {
    errors.push(`missing registrar coverage: ${registrar}`);
  }
}

for (const specifier of surface.pluginSdkExports) {
  if (!sdkImportsSource.includes(`"${specifier}"`)) {
    errors.push(`missing SDK import coverage: ${specifier}`);
  }
}

for (const contract of surface.manifestContracts) {
  if (!Object.hasOwn(manifest.contracts ?? {}, contract)) {
    errors.push(`missing manifest contract coverage: ${contract}`);
  }
}

if (errors.length > 0) {
  throw new Error(errors.join("\n"));
}

console.log(
  `OpenClaw ${surface.packageVersion} surface checked: ${surface.registrars.length} discovered registrars, ${surface.runtimeRegistrars.length} runtime registrar probes, ${surface.hooks.length} hooks, ${surface.manifestContracts.length} manifest contracts, ${surface.pluginSdkExports.length} SDK exports`,
);
for (const registrar of surface.registrars) {
  if (Object.hasOwn(registrarProbeExclusions, registrar)) {
    console.log(`Not exercised on a live host: ${registrar}. ${registrarProbeExclusions[registrar]}`);
  }
}

function read(relativePath) {
  return readFileSync(path.join(rootDir, relativePath), "utf8");
}

#!/usr/bin/env node

import { readFileSync } from "node:fs";
import path from "node:path";
import { readOpenClawSurface } from "./openclaw-surface.mjs";

const rootDir = path.resolve(import.meta.dirname, "..");
const generatedSdkImports = readFileSync(path.join(rootDir, "src/generated-sdk-imports.ts"), "utf8");
const generatedHooks = readFileSync(path.join(rootDir, "src/generated-hooks.js"), "utf8");
const generatedRegistrars = readFileSync(path.join(rootDir, "src/generated-registrars.js"), "utf8");
const manifest = JSON.parse(readFileSync(path.join(rootDir, "openclaw.plugin.json"), "utf8"));
const importedSdkSpecifiers = [
  ...generatedSdkImports.matchAll(/from\s+["'](openclaw\/plugin-sdk(?:\/[^"']+)?)["']/g),
].map((match) => match[1]);
const registeredHooks = [...generatedHooks.matchAll(/api\.on\((["'])([^"']+)\1/g)].map((match) => match[2]).sort();
const coveredRegistrars = [
  ...new Set([
    ...[...generatedRegistrars.matchAll(/safeRegister\((["'])(register[A-Za-z0-9]+)\1/g)].map((match) => match[2]),
    ...[...generatedRegistrars.matchAll(/api\.(register[A-Za-z0-9]+)\(/g)].map((match) => match[1]),
  ]),
].sort();
const manifestContracts = Object.keys(manifest.contracts ?? {}).sort();
const targetSurface = readOpenClawSurface();
const targetSdkExports = new Set(targetSurface.pluginSdkExports);
const importsMissingFromTarget = importedSdkSpecifiers.filter((specifier) => !targetSdkExports.has(specifier));
const targetSdkImportsMissingFromGenerated = targetSurface.pluginSdkExports.filter(
  (specifier) => !importedSdkSpecifiers.includes(specifier),
);
const hookDiff = compareExact("hooks", registeredHooks, targetSurface.hooks);
const registrarDiff = compareExact("registrars", coveredRegistrars, targetSurface.registrars);
const manifestContractDiff = compareExact("manifest contracts", manifestContracts, targetSurface.manifestContracts);
const failures = [];

if (importsMissingFromTarget.length > 0) {
  failures.push(
    `generated SDK imports missing from target OpenClaw ${targetSurface.packageVersion} exports:\n${importsMissingFromTarget.join("\n")}`,
  );
}
if (targetSdkImportsMissingFromGenerated.length > 0) {
  failures.push(
    `target OpenClaw ${targetSurface.packageVersion} SDK exports missing from generated imports:\n${targetSdkImportsMissingFromGenerated.join("\n")}`,
  );
}
for (const diff of [hookDiff, registrarDiff, manifestContractDiff]) {
  if (diff) {
    failures.push(diff);
  }
}

if (failures.length > 0) {
  throw new Error(failures.join("\n\n"));
}

console.log(
  `Generated surface is valid for OpenClaw ${targetSurface.packageVersion}: ${coveredRegistrars.length} registrars, ${registeredHooks.length} hooks, ${manifestContracts.length} manifest contracts, ${importedSdkSpecifiers.length} SDK exports`,
);

function compareExact(label, generated, target) {
  const generatedSet = new Set(generated);
  const targetSet = new Set(target);
  const extra = generated.filter((value) => !targetSet.has(value));
  const missing = target.filter((value) => !generatedSet.has(value));
  if (extra.length === 0 && missing.length === 0) {
    return null;
  }
  return [
    `generated ${label} do not match target OpenClaw ${targetSurface.packageVersion}`,
    extra.length > 0 ? `extra generated ${label}:\n${extra.join("\n")}` : null,
    missing.length > 0 ? `missing generated ${label}:\n${missing.join("\n")}` : null,
  ]
    .filter(Boolean)
    .join("\n");
}

